import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
# Novel candidate: volatility-of-volatility conditioned trend. Trend is 20d return / 20d vol,
# multiplied by a persistence ratio (recent 10d vol / prior 10d vol), clipped: favors trends
# whose volatility is stable/falling, avoiding unstable breakouts.
D={}
for s in U:
 d=get_stock_daily_data(symbol=s,days=310)
 if d is not None:
  d=d.sort_values('date'); c=np.asarray(d.close,float); r=c[1:]/c[:-1]-1
  if len(c)>100: D[s]=(d.date.iloc[1:].values,r,c[1:])
common=max((x[0][0] for x in D.values()),default=None)
# align by date using maps
maps={s:{pd.Timestamp(dt): (float(r[i]),float(c[i])) for i,dt in enumerate(x[0])} for s,x in D.items()}
dates=sorted(set.intersection(*[set(m.keys()) for m in maps.values()])) if len(maps)==15 else []
ics={5:[],10:[],20:[]}; turns=[]; cov=[]; sigrows=[]
prev=None
for j,dt in enumerate(dates):
 if j<65: continue
 vals={}; fw={h:{} for h in ics}
 for s,m in maps.items():
  hist=[m[dates[k]][0] for k in range(j-65,j+1)]
  px=[m[dates[k]][1] for k in range(j-65,j+1)]
  r20=px[-1]/px[-21]-1; v20=np.std(hist[-20:]); v20=max(v20,.002)
  recent=np.std(hist[-10:]); prior=np.std(hist[-20:-10]); persist=np.clip(prior/max(recent,.002),.5,1.5)
  vals[s]=(r20/v20)*persist
  for h in ics: fw[h][s]=m[dates[j+h]][1]/px[-1]-1 if j+h<len(dates) else np.nan
 good=[s for s,v in vals.items() if np.isfinite(v)]
 if len(good)>=8:
  for h in ics:
   pairs=[(vals[s],fw[h][s]) for s in good if np.isfinite(fw[h][s])]
   if len(pairs)>=8: ics[h].append(pd.Series([x[0] for x in pairs]).corr(pd.Series([x[1] for x in pairs]),method='spearman'))
  ranks=pd.Series(vals).rank(pct=True); turns.append(np.mean(np.abs(ranks-(prev if prev is not None else ranks)))) ; prev=ranks
  cov.append(len(good)/15)
  if len(sigrows)<1: sigrows.append((dt,vals))
print('dates',len(dates),'usable',len(cov),'avgN',np.mean([15 for _ in cov]),'coverage',np.mean(cov),'turnover',np.mean(turns))
for h,a in ics.items():
 a=np.array(a); print(h,'IC',np.nanmean(a),'ICIR',np.nanmean(a)/np.nanstd(a,ddof=1),'hit',np.mean(a>0),'n',len(a))
for label,mask in [('2026+', [pd.Timestamp(x)>=pd.Timestamp('2026-01-01') for x in dates[65:]]),('2027+', [pd.Timestamp(x)>=pd.Timestamp('2027-01-01') for x in dates[65:]]),('2028YTD',[pd.Timestamp(x)>=pd.Timestamp('2028-01-01') for x in dates[65:]])]:
 print(label)
 for h,a in ics.items():
  # alignment excludes future tail; approximate use date index and truncate corresponding h
  aa=np.array(a); mm=np.array(mask[:len(aa)])
  z=aa[mm]; print(h,round(np.nanmean(z),6),round(np.nanmean(z)/np.nanstd(z,ddof=1),6),len(z))
# signal artifact (all dates/symbol values) regenerate compact
rows=[]
for dt in dates[65:-20]:
 j=dates.index(dt); row={'date':str(dt)}
 for s,m in maps.items():
  hist=[m[dates[k]][0] for k in range(j-65,j+1)]; px=[m[dates[k]][1] for k in range(j-65,j+1)]
  row[s]=(px[-1]/px[-21]-1)/max(np.std(hist[-20:]),.002)*np.clip(np.std(hist[-20:-10])/max(np.std(hist[-10:]),.002),.5,1.5)
 rows.append(row)
pd.DataFrame(rows).to_csv('scripts/miner_1_20280629_stable_voltrend_signal.csv',index=False)

import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
frames=[]
for s in U:
 d=get_stock_daily_data(symbol=s,days=310)
 if d is not None:
  q=d.sort_values('date')[['date','close']].copy(); q['ret']=q.close.pct_change(); q=q.rename(columns={'close':s,'ret':s+'_r'}); frames.append(q)
# Inner join means explicit common-date cross section
p=frames[0]
for q in frames[1:]: p=p.merge(q,on='date',how='inner')
p=p.sort_values('date').reset_index(drop=True); dates=p.date
ics={5:[],10:[],20:[]}; turns=[]; cov=[]; prev=None
for j in range(65,len(p)-20):
 vals={}; fut={h:{} for h in ics}
 for s in U:
  r=p[s+'_r'].to_numpy(float); px=p[s].to_numpy(float)
  sig=(px[j]/px[j-20]-1)/max(np.std(r[j-19:j+1]),.002)
  sig*=np.clip(np.std(r[j-19:j-1])/max(np.std(r[j-9:j+1]),.002),.5,1.5)
  vals[s]=sig
  for h in ics: fut[h][s]=px[j+h]/px[j]-1
 for h,a in ics.items():
  x=np.array([vals[s] for s in U]); y=np.array([fut[h][s] for s in U])
  if np.std(x)>1e-12 and np.std(y)>1e-12: a.append(pd.Series(x).corr(pd.Series(y),method='spearman'))
 ranks=pd.Series(vals).rank(pct=True); turns.append(np.mean(np.abs(ranks-(prev if prev is not None else ranks)))); prev=ranks; cov.append(1.0)
print('dates',len(p),'usable',len(cov),'avgN',len(U),'coverage',np.mean(cov),'turnover',np.mean(turns))
for h,a in ics.items():
 a=np.asarray(a); print(h,'IC',np.nanmean(a),'ICIR',np.nanmean(a)/np.nanstd(a,ddof=1),'hit',np.mean(a>0),'n',len(a))
 for label,start in [('2026+', '2026-01-01'),('2027+','2027-01-01'),('2028YTD','2028-01-01')]:
  # date mask approximate based on valid signals date
  ds=dates.iloc[65:65+len(a)].to_numpy(); z=a[ds>=np.datetime64(start)]
  print(' ',label,round(np.nanmean(z),6),round(np.nanmean(z)/np.nanstd(z,ddof=1),6),len(z))
rows=[]
for j in range(65,len(p)-20):
 row={'date':str(dates.iloc[j])}
 for s in U:
  r=p[s+'_r'].to_numpy(float); px=p[s].to_numpy(float)
  row[s]=(px[j]/px[j-20]-1)/max(np.std(r[j-19:j+1]),.002)*np.clip(np.std(r[j-19:j-1])/max(np.std(r[j-9:j+1]),.002),.5,1.5)
 rows.append(row)
pd.DataFrame(rows).to_csv('scripts/miner_1_20280629_stable_voltrend_signal.csv',index=False)

