import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_index_daily_data, get_stock_daily_data, get_account_dict

OUT='scripts/miner_1_20290308_updown_vol_balance_signal.csv'
watch=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
frames={}
for s in watch:
    d=get_stock_daily_data(s, days=4000)
    if d is None or len(d)<100: d=get_index_daily_data(s, days=4000)
    if d is not None and len(d):
        d=d.copy(); d['date']=pd.to_datetime(d['date']); d=d.sort_values('date').set_index('date')
        frames[s]=d['close'].astype(float).rename(s)
px=pd.concat(frames,axis=1).sort_index(); ret=px.pct_change()
# lag all information one completed day
r=ret.shift(1); L=30
up=r.clip(lower=0).rolling(L,min_periods=L).std(); dn=(-r.clip(upper=0)).rolling(L,min_periods=L).std()
trend=r.rolling(L,min_periods=L).sum()
# reward persistent upside while penalizing downside variability
sig=(trend*(up+0.002)/(dn+0.002)).replace([np.inf,-np.inf],np.nan).clip(-20,20)
rows=[]; ics={h:[] for h in [5,10,20]}; dates={h:[] for h in [5,10,20]}
for i in range(len(px)):
    for h in [5,10,20]:
        if i+h>=len(px): continue
        a=sig.iloc[i]; f=(px.iloc[i+h]/px.iloc[i]-1)
        z=pd.concat([a,f],axis=1).dropna()
        if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1:
            ics[h].append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); dates[h].append(px.index[i])
    if sig.iloc[i].notna().sum()>=8:
        for s in watch: rows.append({'date':px.index[i], 'symbol':s, 'signal':sig.iloc[i].get(s,np.nan)})
def stats(x):
    x=np.array(x,float); x=x[np.isfinite(x)]; return len(x),float(np.mean(x)),float(np.mean(x)/(np.std(x,ddof=1)+1e-12)),float(np.mean(x>0))
out=pd.DataFrame(rows); out.to_csv(OUT,index=False)
print('dates',len(px),'instruments',len(frames),'signal_rows',len(out))
for h in [5,10,20]:
    n,ic,ir,hit=stats(ics[h]); print('H',h,'valid_dates',n,'IC',round(ic,6),'ICIR',round(ir,6),'hit',round(hit,4))
    for start in ['2026-01-01','2027-01-01','2028-01-01']:
        q=[v for v,d in zip(ics[h],dates[h]) if d>=pd.Timestamp(start)]
        print(start,stats(q))
# avg rank turnover
rank=sig.rank(axis=1,pct=True); print('turnover',float((rank-rank.shift(1)).abs().mean(axis=1).dropna().mean()),'coverage',float(sig.notna().mean().mean()))
print('artifact',OUT)

