import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data
U=["000300.SH","SPX","HSI","N225","SX5E","000688.SH","SOX","NDX","XAU","COPPER","WTI","BTC","ETH","US10Y","CN10Y"]
D={}
for s in U:
 d=get_stock_daily_data(symbol=s,days=4000)
 if d is not None: D[s]=d.sort_values('date').set_index('date')['close'].astype(float)
common=sorted(set.intersection(*[set(D[s].index) for s in U]))
P=pd.DataFrame({s:D[s].reindex(common) for s in U},index=common).ffill(); R=P.pct_change()
# Recovery-quality: medium trend supported by recent trend, penalized by downside volatility.
r20=P.pct_change(20); r60=P.pct_change(60); down=R.where(R<0).rolling(40).std()
raw=(0.65*r20+0.35*r60)/(down*np.sqrt(252)+1e-8)
# cross-sectional rank makes scale robust, lag one completed day
sig=raw.rank(axis=1,pct=True).shift(1); rows=[]; vals={h:[] for h in [1,5,10,20]}; ns={h:[] for h in vals}
for dt in sig.index:
 for h in vals:
  y=P.shift(-h).loc[dt]/P.loc[dt]-1
  z=pd.concat([sig.loc[dt],y],axis=1).dropna()
  if len(z)>=8 and z.iloc[:,0].nunique()>1 and z.iloc[:,1].nunique()>1:
   vals[h].append(z.iloc[:,0].corr(z.iloc[:,1],method='spearman')); ns[h].append(len(z))
for h in vals:
 a=np.asarray(vals[h]); print('%dd dates=%d avgN=%.2f IC=%.6f ICIR=%.6f hit=%.4f'%(h,len(a),np.mean(ns[h]),np.nanmean(a),np.nanmean(a)/np.nanstd(a,ddof=1),np.mean(a>0)))
print('coverage %.4f turnover %.6f'%(np.isfinite(sig).mean().mean(),sig.diff().abs().mean(axis=1).dropna().mean()))
out=pd.DataFrame({'date':sig.index});
for s in U: out[s]=sig[s].values
out.to_csv('scripts/miner_1_20300822_recovery_quality_signal.csv',index=False)

