U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
# Macro-conditioned, lagged 10d trend: trend is favored in calm VIX, reversed in stressed regimes.
D={}
for s in U:
 d=get_index_daily_data(s,days=5000)
 if d is not None and len(d): D[s]=d.set_index(pd.to_datetime(d.date)).close.astype(float)
p=pd.DataFrame(D).sort_index().ffill()
v=pd.read_csv('../persistent/index_data/VIX.csv')
v['date']=pd.to_datetime(v['date']); v=v.set_index('date'); vc=[c for c in v.columns if c.lower() in ('close','value','price')][0]
v=v[vc].reindex(p.index).ffill()
# lagged signal: 10d return / 20d vol, multiplied by calm-state sign/strength
r=p.pct_change(); vol=r.rolling(20).std(); base=p.shift(1).pct_change(10)/vol.shift(1)
z=(v.shift(1)-v.shift(1).rolling(252).median())/v.shift(1).rolling(252).std()
# calm positive trend, stress contrarian (interpretable hard regime)
f=base.where(z<0,-base)
rows=[]
for h in [1,5,10,20]:
