import pandas as pd,numpy as np,glob,os
from scipy.stats import spearmanr
D={}
for f in glob.glob('../persistent/stock_data/*.csv'):
 s=os.path.basename(f)[:-4]; D[s]=pd.read_csv(f,parse_dates=['date']).set_index('date').sort_index()
C=pd.DataFrame({s:d.close for s,d in D.items()}); R=C.pct_change()
# volatility-conditioned short-term reversal: 5d reversal amplified when cross-sectional dispersion is high
mom=C.pct_change(5); disp=R.std(axis=1).rolling(20).mean(); breadth=(R.rolling(20).mean()>0).mean(axis=1)
# lag all components, interpretable: negative short momentum, scaled by dispersion and market breadth
sig=(-mom * (disp/disp.rolling(120).median()).clip(.5,2) * (0.75+0.5*breadth)).shift(1)
res={h:[] for h in [1,5,10,20]}; ds={h:[] for h in res}
for dt in sig.index:
 for h in res:
