import numpy as np, pandas as pd
from alphacrafter.sim.utils import get_stock_daily_data, get_index_daily_data
U=['000300.SH','SPX','HSI','N225','SX5E','000688.SH','SOX','NDX','XAU','COPPER','WTI','BTC','ETH','US10Y','CN10Y']
def fetch(s): return get_stock_daily_data(s,days=5000)
px={s:fetch(s) for s in U}
px={s:d.set_index('date')['close'].astype(float) for s,d in px.items() if d is not None and len(d)>300}
c=pd.concat(px,axis=1).sort_index().ffill(); r=np.log(c).diff()
vix=get_index_daily_data('VIX',days=5000).set_index('date')['close'].astype(float).reindex(c.index).ffill()
raw20=r.rolling(20).sum(); resid=raw20.sub(raw20.median(axis=1),axis=0); vol=r.rolling(20).std()*np.sqrt(20)
vz=(vix-vix.rolling(120).mean())/(vix.rolling(120).std()+1e-12)
f=(-resid/(vol+1e-12))*(1+0.35*np.tanh(vz)); fr=np.log(c.shift(-20)/c)
rows=[]; dates=[]; ns=[]
for dt in f.index:
 ok=f.loc[dt].notna()&fr.loc[dt].notna()
 if ok.sum()>=8: rows.append(f.loc[dt][ok].corr(fr.loc[dt][ok])); dates.append(dt); ns.append(ok.sum())
ic=pd.Series(rows,index=dates).dropna()
print('assets',len(px),'dates',len(ic),'avg_n',np.mean(ns),'coverage',len(ic)/(len(f)-20),'IC',ic.mean(),'ICIR',ic.mean()/ic.std(ddof=1),'hit',(ic>0).mean())
for h in [1,5,10,20,40]:
 yy=np.log(c.shift(-h)/c); vals=[]
 for dt in f.index:
  ok=f.loc[dt].notna()&yy.loc[dt].notna()
  if ok.sum()>=8: vals.append(f.loc[dt][ok].corr(yy.loc[dt][ok]))
 print('decay',h,np.nanmean(vals))
rank=f.rank(axis=1,pct=True); print('turnover10',((rank-rank.shift(10)).abs().mean().mean()))
for a,b in [('2020','2022'),('2023','2025'),('2026','2028'),('2029','2030'),('2031','2032')]:
 z=ic.loc[a:b]; print('regime',a,b,len(z),z.mean(),z.mean()/z.std(ddof=1) if len(z)>1 else np.nan)
f.index.name='date'; f.reset_index().to_csv('scripts/miner_1_20320108_macro_stress_reversal_signal.csv',index=False)

